    s.angle = next; s.autoAngle = next; s.lastStep = now;
}

// ---------- dead / stuck sensor detection ----------
// A dead sensor often reads a perfectly plausible number (0, or the same value forever), so the range check never catches it.
// This returns the sensors that look dead on THIS reading. handleReading then treats them like confirmed bad readings:
// SENSOR_FAULT alert, sensorFault on the dashboard, and the zone falls back to open loop (it follows its share).
function detectDead(z, r) {
    var s = S.z[z];
    if (!s.dead) s.dead = { zeroN: 0, flat: {} };
    var D = s.dead, res = [];
    // the valve is really commanded open: valve commands started, zone not closed, angle at or above the minimum
    var open = s.synced && s.mode !== 'closed' && s.angle >= CFG.DEAD_FLOW_MIN_ANGLE;
    // 1) flow reads zero while the valve is open
    if (CFG.DEAD_FLOW_READINGS > 0 && open && r.flow !== null && r.flow !== undefined && r.flow <= CFG.DEAD_FLOW_ZERO) {
        D.zeroN++;
        if (D.zeroN >= CFG.DEAD_FLOW_READINGS) res.push('flow');
    } else {
        D.zeroN = 0;
    }
    // 2) flatline: exactly the same value for N readings in a row
    if (CFG.FLATLINE_READINGS > 0) {
        CFG.FLATLINE_SENSORS.forEach(function (k) {
            var v = r[k];
            if (v === null || v === undefined || (k === 'flow' && !open)) { D.flat[k] = null; return; }   // a closed zone legitimately has a steady flow
            var f = D.flat[k];
            if (!f || Math.abs(v - f.v) > CFG.FLATLINE_TOLERANCE) { D.flat[k] = { v: v, n: 1 }; return; }
            f.n++;
            if (f.n >= CFG.FLATLINE_READINGS && res.indexOf(k) === -1) res.push(k);
        });
    }
    return res;
}

// ---------- handlers ----------
function handleReading(z, r, bad) {
    var s = S.z[z];
    if (s.count < CFG.DISCARD_FIRST) { s.count++; return; }   // first reading after start is dropped
    if (CFG.DEAD_SENSOR_ENABLED) {                            // dead / stuck sensors are handled like confirmed bad ones
        var dead = detectDead(z, r);
        if (dead.length) {
            r = Object.assign({}, r);
            bad = bad.slice();
            dead.forEach(function (k) {
                r[k] = null;
                if (bad.indexOf(k) === -1) bad.push(k);
                s.badCount[k] = Math.max(s.badCount[k] || 0, CFG.FAULT_READINGS - 1);   // the loop below adds 1 -> confirmed on this reading
            });
        }
    }
    s.lastRaw = r; s.bad = bad;
    KEYS.forEach(function (k) {
        if (!s.buf[k]) s.buf[k] = [];
        if (r[k] === null || r[k] === undefined) {
            if (k === 'soil') { s.buf[k] = []; return; }            // soil missing is never a fault
            s.badCount[k] = (s.badCount[k] || 0) + 1;
            if (s.badCount[k] >= CFG.FAULT_READINGS) s.buf[k] = []; // confirmed broken: forget old values
            return;                                                 // otherwise keep the last good values
        }
        s.badCount[k] = 0;
        s.buf[k].push(r[k]);
        if (s.buf[k].length > CFG.SMOOTH_N) s.buf[k].shift();
    });
    var sm = {};
    KEYS.forEach(function (k) { sm[k] = avg(s.buf[k]); });
    s.lastSm = sm;
    if (z === 'farm') {
        if (sm.rain !== null && sm.rain >= CFG.RAIN_WET_THRESHOLD) s.lastRain = now;
        s.soilWet = s.lastRain !== null && now - s.lastRain < CFG.WET_MS;
    }
    var confirmed = bad.filter(function (k) { return (s.badCount[k] || 0) >= CFG.FAULT_READINGS; });
    s.bad = confirmed;                                        // only confirmed faults are reported
    evalAlarms(z, r, confirmed);
    evalModeAlerts();
    if (r.level !== null) {
        s.critHigh = isAct(z, 'LEVEL_HIGH');
        s.critLow = isAct(z, 'LEVEL_LOW');
    } else if (confirmed.indexOf('level') !== -1) {           // level sensor really broken: safety flags off
        s.critHigh = false; s.critLow = false;
    }                                                         // one glitch: keep the previous flags

    if (s.mode !== 'closed' && CFG.REF_RULE_ENABLED && s.refPending !== null && now >= s.refPending && sm.flow !== null) {
        if (s.preFlow === null || sm.flow > s.preFlow) s.refMax = clamp(CFG.REF_FACTOR * sm.flow, CFG.FLOW_TARGET_MIN, CFG.FLOW_SCALE);
        s.refPending = null;
    }
    s.demand = computeDemand(z, sm, s);
    if (s.demand !== null) {
        if (CFG.SUPPLY_ENABLED) {
            s.need = CFG.FLOW_TARGET_MIN + s.demand / 100 * (CFG.FLOW_TARGET_MAX - CFG.FLOW_TARGET_MIN);
            reallocate();                                    // sets s.target from the shared supply
        } else {
            var ref = Math.max(s.refMax, CFG.FLOW_TARGET_MIN);
            s.target = CFG.FLOW_TARGET_MIN + s.demand / 100 * (ref - CFG.FLOW_TARGET_MIN);
        }
    }
    if (now - S.t0 >= CFG.STARTUP_HOLD_MS) {
        if (!s.synced) { s.synced = true; sendValve(z); }
        if (s.mode === 'auto') {
            var before = Math.round(s.angle);
            controlStep(z, sm, s);
            if (Math.round(s.angle) !== before) { sendValve(z); sendSave(z); }
        }
    }
    pushDash(z, false);
}

function handleCommand(z, p) {
    var s = S.z[z], m = p.method;
    if (m === 'getMode') { sendReply(z, p.rpcId, true); return; }
    if (m === 'setMode') {
        var want = typeof p.params === 'string' ? p.params.trim().toLowerCase() : p.params;
        if (['auto', 'closed', 'manual'].indexOf(want) === -1) { sendReply(z, p.rpcId, false, 'Invalid mode. Use auto, closed or manual.'); return; }
        if (want === s.mode) { sendReply(z, p.rpcId, true); return; }
        var prev = s.mode;
        s.mode = want; s.modeSince = now;
        if (want === 'closed') {
            s.angle = 0;
        } else if (want === 'auto') {
            s.angle = prev === 'closed' ? s.autoAngle : clamp(s.angle, CFG.AUTO_MIN, CFG.AUTO_MAX);
            s.angle = clamp(s.angle, CFG.AUTO_MIN, CFG.AUTO_MAX);
            s.autoAngle = s.angle; s.lastStep = now;
        } else {
            s.manualAngle = Math.round(s.angle);              // keep the current angle
        }
        sendValve(z); sendSave(z);
        updateClosed(); evalModeAlerts(); reallocate();
        sendReply(z, p.rpcId, true);
        pushDash(z, true);
        return;
    }
    if (m === 'setValve') {
        if (s.mode !== 'manual') {
            sendAlert(z, 'CMD_REJECTED', 'alarm', undefined, 'Valve command ignored: the zone is not in manual mode. Change the mode to manual first.');
            sendReply(z, p.rpcId, false, 'Not in manual mode. Change the mode to manual first.');
            return;
        }
        var a = Number(p.params);
        if (p.params === null || p.params === undefined || p.params === '' || !isFinite(a) || a < CFG.SERVO_MIN || a > CFG.SERVO_MAX) {
            sendReply(z, p.rpcId, false, 'Invalid angle. Use a number from ' + CFG.SERVO_MIN + ' to ' + CFG.SERVO_MAX + '.');
            return;
        }
        s.manualAngle = Math.round(a); s.angle = s.manualAngle;
        sendValve(z); sendSave(z);
        evalModeAlerts(); reallocate();
        sendReply(z, p.rpcId, true);
        pushDash(z, true);
        return;
    }
    sendReply(z, p.rpcId, false, 'Unknown method: ' + m);
}

function handleRestore(z, p) {
    var s = S.z[z];
    s.mode = p.mode; s.modeSince = now;
    s.manualAngle = Number(p.manualAngle) || 0;
    var la = (p.lastAngle === null || p.lastAngle === undefined) ? NaN : Number(p.lastAngle);
    s.autoAngle = isFinite(la) ? clamp(la, CFG.AUTO_MIN, CFG.AUTO_MAX) : CFG.START_ANGLE;
    s.angle = p.mode === 'closed' ? 0 : (p.mode === 'manual' ? s.manualAngle : s.autoAngle);
    s.lastStep = now;
    if (p.mode === 'closed') silentActive(z, 'ZONE_CLOSED');
    if (p.mode === 'manual') silentActive(z, 'ZONE_MANUAL');
    updateClosed(); reallocate();
    if (S.closedCount >= 2) silentActive('all', 'MULTI_CLOSED');
}

// ---------- main ----------
if (!S.z[msg.zone]) return null;
if (msg.kind === 'reading') handleReading(msg.zone, msg.payload, msg.bad || []);
else if (msg.kind === 'command') handleCommand(msg.zone, msg.payload || {});
else if (msg.kind === 'restore') handleRestore(msg.zone, msg.payload || {});
else return null;

return out.map(function (a) { return a.length ? a : null; });

